struct seq_hdr { uint32_t seq_id, position, size; };

/* sender */
mq_send(q, frame(&hdr, part), frame_len, 0);

/* receiver */
struct slot *s = slot_get(hdr.seq_id);        /* created on demand */
store_part(s, hdr.position, part);
if (++s->have == hdr.size)
    deliver(s);                               /* in position order */
